135 struct aiFace {
138     unsigned int mNumIndices;
139 
141     unsigned int *mIndices;
142 
143 #ifdef __cplusplus
144 
146     aiFace() AI_NO_EXCEPT
147             : mNumIndices(0),
148               mIndices(nullptr) {
149         // empty
150     }
151 
153     ~aiFace() {
154         delete[] mIndices;
155     }
156 
158     aiFace(const aiFace &o) :
159             mNumIndices(0), mIndices(nullptr) {
160         *this = o;
161     }
162 
164     aiFace &operator=(const aiFace &o) {
165         if (&o == this) {
166             return *this;
167         }
168 
169         delete[] mIndices;
170         mNumIndices = o.mNumIndices;
171         if (mNumIndices) {
172             mIndices = new unsigned int[mNumIndices];
173             ::memcpy(mIndices, o.mIndices, mNumIndices * sizeof(unsigned int));
174         } else {
175             mIndices = nullptr;
176         }
177 
178         return *this;
179     }
180 
183     bool operator==(const aiFace &o) const {
184         if (mIndices == o.mIndices) {
185             return true;
186         }
187 
188         if (nullptr != mIndices && mNumIndices != o.mNumIndices) {
189             return false;
190         }
191 
192         if (nullptr == mIndices) {
193             return false;
194         }
195 
196         for (unsigned int i = 0; i < this->mNumIndices; ++i) {
197             if (mIndices[i] != o.mIndices[i]) {
198                 return false;
199             }
200         }
201 
202         return true;
203     }
204 
207     bool operator!=(const aiFace &o) const {
208         return !(*this == o);
209     }
210 #endif // __cplusplus
211 }; // struct aiFace
