263 struct aiBone {
265     C_STRUCT aiString mName;
266 
269     unsigned int mNumWeights;
270 
271 #ifndef ASSIMP_BUILD_NO_ARMATUREPOPULATE_PROCESS
274     C_STRUCT aiNode *mArmature;
275 
278     C_STRUCT aiNode *mNode;
279 
280 #endif
282     C_STRUCT aiVertexWeight *mWeights;
283 
295     C_STRUCT aiMatrix4x4 mOffsetMatrix;
296 
297 #ifdef __cplusplus
298 
300     aiBone() AI_NO_EXCEPT
301             : mName(),
302               mNumWeights(0),
303 #ifndef ASSIMP_BUILD_NO_ARMATUREPOPULATE_PROCESS
304               mArmature(nullptr),
305               mNode(nullptr),
306 #endif
307               mWeights(nullptr),
308               mOffsetMatrix() {
309         // empty
310     }
311 
313     aiBone(const aiBone &other) :
314             mName(other.mName),
315             mNumWeights(other.mNumWeights),
316 #ifndef ASSIMP_BUILD_NO_ARMATUREPOPULATE_PROCESS
317               mArmature(nullptr),
318               mNode(nullptr),
319 #endif
320             mWeights(nullptr),
321             mOffsetMatrix(other.mOffsetMatrix) {
322         copyVertexWeights(other);
323     }
324 
325     void copyVertexWeights( const aiBone &other ) {
326         if (other.mWeights == nullptr || other.mNumWeights == 0) {
327             mWeights = nullptr;
328             mNumWeights = 0;
329             return;
330         }
331 
332         mNumWeights = other.mNumWeights;
333         if (mWeights) {
334             delete[] mWeights;
335         }
336 
337         mWeights = new aiVertexWeight[mNumWeights];
338         ::memcpy(mWeights, other.mWeights, mNumWeights * sizeof(aiVertexWeight));
339     }
340 
342     aiBone &operator = (const aiBone &other) {
343         if (this == &other) {
344             return *this;
345         }
346 
347         mName = other.mName;
348         mNumWeights = other.mNumWeights;
349         mOffsetMatrix = other.mOffsetMatrix;
350         copyVertexWeights(other);
351 
352         return *this;
353     }
354 
355     bool operator==(const aiBone &rhs) const {
356         if (mName != rhs.mName || mNumWeights != rhs.mNumWeights ) {
357             return false;
358         }
359 
360         for (size_t i = 0; i < mNumWeights; ++i) {
361             if (mWeights[i] != rhs.mWeights[i]) {
362                 return false;
363             }
364         }
365 
366         return true;
367     }
369     ~aiBone() {
370         delete[] mWeights;
371     }
372 #endif // __cplusplus
373 };
