439 // Get the #aiPrimitiveType flag for a specific number of face indices
440 #define AI_PRIMITIVE_TYPE_FOR_N_INDICES(n) \
441     ((n) > 3 ? aiPrimitiveType_POLYGON : (aiPrimitiveType)(1u << ((n)-1)))
