454 struct aiAnimMesh {
456     C_STRUCT aiString mName;
457 
464     C_STRUCT aiVector3D *mVertices;
465 
467     C_STRUCT aiVector3D *mNormals;
468 
470     C_STRUCT aiVector3D *mTangents;
471 
473     C_STRUCT aiVector3D *mBitangents;
474 
476     C_STRUCT aiColor4D *mColors[AI_MAX_NUMBER_OF_COLOR_SETS];
477 
479     C_STRUCT aiVector3D *mTextureCoords[AI_MAX_NUMBER_OF_TEXTURECOORDS];
480 
489     unsigned int mNumVertices;
490 
494     float mWeight;
495 
496 #ifdef __cplusplus
497 
498     aiAnimMesh() AI_NO_EXCEPT
499             : mVertices(nullptr),
500               mNormals(nullptr),
501               mTangents(nullptr),
502               mBitangents(nullptr),
503               mColors(),
504               mTextureCoords(),
505               mNumVertices(0),
506               mWeight(0.0f) {
507         // fixme consider moving this to the ctor initializer list as well
508         for (unsigned int a = 0; a < AI_MAX_NUMBER_OF_TEXTURECOORDS; a++) {
509             mTextureCoords[a] = nullptr;
510         }
511         for (unsigned int a = 0; a < AI_MAX_NUMBER_OF_COLOR_SETS; a++) {
512             mColors[a] = nullptr;
513         }
514     }
515 
516     ~aiAnimMesh() {
517         delete[] mVertices;
518         delete[] mNormals;
519         delete[] mTangents;
520         delete[] mBitangents;
521         for (unsigned int a = 0; a < AI_MAX_NUMBER_OF_TEXTURECOORDS; a++) {
522             delete[] mTextureCoords[a];
523         }
524         for (unsigned int a = 0; a < AI_MAX_NUMBER_OF_COLOR_SETS; a++) {
525             delete[] mColors[a];
526         }
527     }
528 
531     bool HasPositions() const {
532         return mVertices != nullptr;
533     }
534 
537     bool HasNormals() const {
538         return mNormals != nullptr;
539     }
540 
544     bool HasTangentsAndBitangents() const {
545         return mTangents != nullptr;
546     }
547 
551     bool HasVertexColors(unsigned int pIndex) const {
552         return pIndex >= AI_MAX_NUMBER_OF_COLOR_SETS ? false : mColors[pIndex] != nullptr;
553     }
554 
558     bool HasTextureCoords(unsigned int pIndex) const {
559         return pIndex >= AI_MAX_NUMBER_OF_TEXTURECOORDS ? false : mTextureCoords[pIndex] != nullptr;
560     }
561 
562 #endif
563 };
