605 struct aiMesh {
611     unsigned int mPrimitiveTypes;
612 
617     unsigned int mNumVertices;
618 
623     unsigned int mNumFaces;
624 
629     C_STRUCT aiVector3D *mVertices;
630 
651     C_STRUCT aiVector3D *mNormals;
652 
665     C_STRUCT aiVector3D *mTangents;
666 
674     C_STRUCT aiVector3D *mBitangents;
675 
681     C_STRUCT aiColor4D *mColors[AI_MAX_NUMBER_OF_COLOR_SETS];
682 
687     C_STRUCT aiVector3D *mTextureCoords[AI_MAX_NUMBER_OF_TEXTURECOORDS];
688 
696     unsigned int mNumUVComponents[AI_MAX_NUMBER_OF_TEXTURECOORDS];
697 
704     C_STRUCT aiFace *mFaces;
705 
709     unsigned int mNumBones;
710 
715     C_STRUCT aiBone **mBones;
716 
722     unsigned int mMaterialIndex;
723 
735     C_STRUCT aiString mName;
736 
738     unsigned int mNumAnimMeshes;
739 
744     C_STRUCT aiAnimMesh **mAnimMeshes;
745 
750     unsigned int mMethod;
751 
755     C_STRUCT aiAABB mAABB;
756 
759     C_STRUCT aiString **mTextureCoordsNames;
760 
761 #ifdef __cplusplus
762 
764     aiMesh() AI_NO_EXCEPT
765             : mPrimitiveTypes(0),
766               mNumVertices(0),
767               mNumFaces(0),
768               mVertices(nullptr),
769               mNormals(nullptr),
770               mTangents(nullptr),
771               mBitangents(nullptr),
772               mColors(),
773               mTextureCoords(),
774               mNumUVComponents(),
775               mFaces(nullptr),
776               mNumBones(0),
777               mBones(nullptr),
778               mMaterialIndex(0),
779               mNumAnimMeshes(0),
780               mAnimMeshes(nullptr),
781               mMethod(0),
782               mAABB(),
783               mTextureCoordsNames(nullptr) {
784         for (unsigned int a = 0; a < AI_MAX_NUMBER_OF_TEXTURECOORDS; ++a) {
785             mNumUVComponents[a] = 0;
786             mTextureCoords[a] = nullptr;
787         }
788 
789         for (unsigned int a = 0; a < AI_MAX_NUMBER_OF_COLOR_SETS; ++a) {
790             mColors[a] = nullptr;
791         }
792     }
793 
795     ~aiMesh() {
796         delete[] mVertices;
797         delete[] mNormals;
798         delete[] mTangents;
799         delete[] mBitangents;
800         for (unsigned int a = 0; a < AI_MAX_NUMBER_OF_TEXTURECOORDS; a++) {
801             delete[] mTextureCoords[a];
802         }
803 
804         if (mTextureCoordsNames) {
805             for (unsigned int a = 0; a < AI_MAX_NUMBER_OF_TEXTURECOORDS; a++) {
806                 delete mTextureCoordsNames[a];
807             }
808             delete[] mTextureCoordsNames;
809         }
810 
811         for (unsigned int a = 0; a < AI_MAX_NUMBER_OF_COLOR_SETS; a++) {
812             delete[] mColors[a];
813         }
814 
815         // DO NOT REMOVE THIS ADDITIONAL CHECK
816         if (mNumBones && mBones) {
817             for (unsigned int a = 0; a < mNumBones; a++) {
818                 if (mBones[a]) {
819                     delete mBones[a];
820                 }
821             }
822             delete[] mBones;
823         }
824 
825         if (mNumAnimMeshes && mAnimMeshes) {
826             for (unsigned int a = 0; a < mNumAnimMeshes; a++) {
827                 delete mAnimMeshes[a];
828             }
829             delete[] mAnimMeshes;
830         }
831 
832         delete[] mFaces;
833     }
834 
837     bool HasPositions() const { return mVertices != nullptr && mNumVertices > 0; }
838 
841     bool HasFaces() const { return mFaces != nullptr && mNumFaces > 0; }
842 
844     bool HasNormals() const { return mNormals != nullptr && mNumVertices > 0; }
845 
850     bool HasTangentsAndBitangents() const { return mTangents != nullptr && mBitangents != nullptr && mNumVertices > 0; }
851 
854     bool HasVertexColors(unsigned int pIndex) const {
855         if (pIndex >= AI_MAX_NUMBER_OF_COLOR_SETS) {
856             return false;
857         } else {
858             return mColors[pIndex] != nullptr && mNumVertices > 0;
859         }
860     }
861 
864     bool HasTextureCoords(unsigned int pIndex) const {
865         if (pIndex >= AI_MAX_NUMBER_OF_TEXTURECOORDS) {
866             return false;
867         } else {
868             return mTextureCoords[pIndex] != nullptr && mNumVertices > 0;
869         }
870     }
871 
873     unsigned int GetNumUVChannels() const {
874         unsigned int n(0);
875         while (n < AI_MAX_NUMBER_OF_TEXTURECOORDS && mTextureCoords[n]) {
876             ++n;
877         }
878 
879         return n;
880     }
881 
883     unsigned int GetNumColorChannels() const {
884         unsigned int n(0);
885         while (n < AI_MAX_NUMBER_OF_COLOR_SETS && mColors[n]) {
886             ++n;
887         }
888         return n;
889     }
890 
892     bool HasBones() const {
893         return mBones != nullptr && mNumBones > 0;
894     }
895 
898     bool HasTextureCoordsName(unsigned int pIndex) const {
899         if (mTextureCoordsNames == nullptr || pIndex >= AI_MAX_NUMBER_OF_TEXTURECOORDS) {
900             return false;
901         }
902         return mTextureCoordsNames[pIndex] != nullptr;
903     }
904 
908     void SetTextureCoordsName(unsigned int pIndex, const aiString &texCoordsName) {
909         if (pIndex >= AI_MAX_NUMBER_OF_TEXTURECOORDS) {
910             return;
911         }
912 
913         if (mTextureCoordsNames == nullptr) {
914             // Construct and null-init array
915             mTextureCoordsNames = new aiString *[AI_MAX_NUMBER_OF_TEXTURECOORDS] {};
916         }
917 
918         if (texCoordsName.length == 0) {
919             delete mTextureCoordsNames[pIndex];
920             mTextureCoordsNames[pIndex] = nullptr;
921             return;
922         }
923 
924         if (mTextureCoordsNames[pIndex] == nullptr) {
925             mTextureCoordsNames[pIndex] = new aiString(texCoordsName);
926             return;
927         }
928 
929         *mTextureCoordsNames[pIndex] = texCoordsName;
930     }
931 
934     const aiString *GetTextureCoordsName(unsigned int pIndex) const {
935         if (mTextureCoordsNames == nullptr || pIndex >= AI_MAX_NUMBER_OF_TEXTURECOORDS) {
936             return nullptr;
937         }
938 
939         return mTextureCoordsNames[pIndex];
940     }
941 
942 #endif // __cplusplus
943 };
